import os, csv, json
from pathlib import Path

DIR = Path(os.environ["PIPELINE_FLOW_DIR"])
dates = ["20191201", "20191202", "20191203", "20191204", "20191205"]

targets = [
    ("靖边站", "石家庄站", "陕京二线"),
    ("安平站", "南京站", "冀宁线"),
]

# accumulate per (start,end,pipeline): list of daily values
acc = {t: {} for t in targets}
missing = []

for d in dates:
    fp = DIR / f"{d}_pipeline.csv"
    if not fp.exists():
        missing.append(d)
        continue
    with open(fp, encoding="utf-8") as f:
        reader = csv.DictReader(f)
        for row in reader:
            key = (row["起点站名"].strip(), row["终点站名"].strip(), row["管道划分"].strip())
            if key in acc:
                acc[key][d] = float(row["管道流量"])

result = {}
for key, daily in acc.items():
    vals = [daily.get(d) for d in dates]
    total_abs = sum(abs(v) for v in vals if v is not None)
    result[f"{key[0]}->{key[1]}|{key[2]}"] = {
        "daily": {d: daily.get(d) for d in dates},
        "days_present": sum(1 for v in vals if v is not None),
        "cum_abs_flow": total_abs,
    }

print(json.dumps({"missing_files": missing, "result": result}, ensure_ascii=False, indent=2, default=str))

import csv,hashlib,json,os
from decimal import Decimal
from pathlib import Path
root=Path(os.environ['PIPELINE_FLOW_DIR'])
pairs={frozenset(('靖边站','石家庄站')),frozenset(('安平站','南京站'))}
totals={'陕京二线':Decimal(0),'冀宁线':Decimal(0)}
rows=[]
refs=[]
for d in range(1,6):
    p=root/f'201912{d:02}_pipeline.csv'
    refs.append({'file':p.name,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()})
    with p.open(encoding='utf-8-sig',newline='') as f:
        for r in csv.DictReader(f):
            if r['管道划分'] in totals and frozenset((r['起点站名'],r['终点站名'])) in pairs:
                totals[r['管道划分']]+=abs(Decimal(r['管道流量']))
                rows.append({'file':p.name,**r})
assert len(rows)==15
assert totals=={'陕京二线':Decimal('6298.698'),'冀宁线':Decimal('9805.853')}
result={'matched_rows':len(rows),'rows':rows,'source_refs':refs,'totals':{k:str(v) for k,v in totals.items()},'difference_jining_minus_shaanjing':str(totals['冀宁线']-totals['陕京二线'])}
print(json.dumps(result,ensure_ascii=False))

