# Candidate boundary-control schemes for mock_test case 1073
# Disturbance: T_001:SNQ +7%
# Horizon: 360 minutes (6 hours)

# Candidate 1: Boost primary compressor C_001 to support increased flow
# Candidate 1: Increase C_001:SP_ by 5%, adjust R_001:SPD by +3%
candidate_1 = {
    "name": "primary_compressor_boost",
    "description": "Increase C_001 compressor speed setpoint 5% and R_001 regulator speed 3% to support elevated flow",
    "boundary_conditions": {
        "keep_other_boundary_controls": True,
        "percentage_changes": {
            "C_001:SP_": 5.0,
            "R_001:SPD": 3.0
        }
    }
}

# Candidate 2: Distributed compressor adjustment across parallel units
# Candidate 2: Increase C_005:SP_ by 4%, C_014:SP_out by 4%, R_004:SPD by 2%
candidate_2 = {
    "name": "distributed_compressor_adjustment",
    "description": "Increase C_005 and C_014 compressor setpoints 4% each, with minor R_004 regulator adjustment 2%",
    "boundary_conditions": {
        "keep_other_boundary_controls": True,
        "percentage_changes": {
            "C_005:SP_": 4.0,
            "C_014:SP_out": 4.0,
            "R_004:SPD": 2.0
        }
    }
}

# Candidate 3: Regulator-focused pressure management
# Candidate 3: Increase R_005:ST to 1 (activate pressure regulation), R_007:SPD +5%, C_019:SP_out +3%
candidate_3 = {
    "name": "regulator_led_pressure_management",
    "description": "Activate R_005:ST, increase R_007 regulator speed 5%, C_019 compressor 3% for pressure support",
    "boundary_conditions": {
        "keep_other_boundary_controls": True,
        "setpoints": {
            "R_005:ST": 1
        },
        "percentage_changes": {
            "R_007:SPD": 5.0,
            "C_019:SP_out": 3.0
        }
    }
}

candidates = [candidate_1, candidate_2, candidate_3]

for i, c in enumerate(candidates, 1):
    print(f"Candidate {i}: {c['name']}")
    print(f"  Description: {c['description']}")
    print(f"  Boundary Conditions: {c['boundary_conditions']}")
    print()

