import os
import csv
from pathlib import Path
from collections import deque

# Get the directory paths from environment variables
node_dir = Path(os.environ["NODE_FLOW_DIR"])
pipeline_dir = Path(os.environ["PIPELINE_FLOW_DIR"])

node_file = node_dir / "20191204_node.csv"
pipeline_file = pipeline_dir / "20191204_pipeline.csv"

# Read pipeline data
pipelines = []
with open(pipeline_file, 'r', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    for row in reader:
        pipelines.append({
            'start': row['起点站名'],
            'end': row['终点站名'],
            'type': row['类型'],
            'line': row['管道划分'],
            'flow': float(row['管道流量'])
        })

# Read node data to identify source types
node_data = {}
with open(node_file, 'r', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    for row in reader:
        station = row['站名']
        if station not in node_data:
            node_data[station] = []
        node_data[station].append({
            'line': row['管道划分'],
            'type': row['类型'],
            'control_type': row['控制类型'],
            'input_flow': row['输入流量'],
            'calc_flow': row['计算流量']
        })

# Build forward graph: start -> [end stations]
graph_forward = {}
for p in pipelines:
    start = p['start']
    end = p['end']
    if start not in graph_forward:
        graph_forward[start] = []
    graph_forward[start].append({
        'station': end,
        'line': p['line'],
        'flow': p['flow']
    })

# Identify sources (气源 type nodes)
sources = set()
for station, infos in node_data.items():
    for info in infos:
        if info['type'] == '气源':
            sources.add(station)

# Build reverse graph: end -> [start stations]
graph_reverse = {}
for p in pipelines:
    end = p['end']
    start = p['start']
    if end not in graph_reverse:
        graph_reverse[end] = []
    graph_reverse[end].append({
        'station': start,
        'line': p['line'],
        'flow': p['flow']
    })

# Check what stations are connected to 华阴站
target = '华阴站'

print("=" * 60)
print(f"CONNECTIVITY ANALYSIS FOR {target}")
print("=" * 60)

# Check if 华阴站 appears as endpoint
print(f"\n[target as endpoint] Pipelines where {target} is the end:")
for p in pipelines:
    if p['end'] == target:
        print(f"  {p['start']} -> {p['end']} ({p['line']}, flow: {p['flow']})")

if not any(p['end'] == target for p in pipelines):
    print("  None found - 华阴站 never appears as a destination (end) in any pipeline")

# Check if 华阴站 appears as start
print(f"\n[华阴站 as start] Pipelines where {target} is the start:")
for p in pipelines:
    if p['start'] == target:
        print(f"  {p['start']} -> {p['end']} ({p['line']}, flow: {p['flow']})")

# Check node data
print(f"\n[node data] {target} appears as:")
if target in node_data:
    for info in node_data[target]:
        print(f"  Line: {info['line']}, Type: {info['type']}, Control: {info['control_type']}, Calc Flow: {info['calc_flow']}")

# Now let's trace all possible paths in the network
# Forward traversal from all sources
print("\n" + "=" * 60)
print("FORWARD TRAVERSAL FROM ALL SOURCES")
print("=" * 60)

reachable_from_sources = set()

for src in sorted(sources):
    print(f"\n[source] {src}")
    visited_local = set()
    queue = deque([src])
    visited_local.add(src)

    while queue:
        current = queue.popleft()
        if current in graph_forward:
            for conn in graph_forward[current]:
                next_station = conn['station']
                if next_station not in visited_local:
                    visited_local.add(next_station)
                    queue.append(next_station)
                    reachable_from_sources.add(next_station)

    print(f"  Reachable stations: {sorted(visited_local)}")
    print(f"  {target} in reachable: {target in visited_local}")

# Check all stations and their position relative to 华阴站
print("\n" + "=" * 60)
print("ALL STATIONS - POSITION RELATIVE TO 华阴站")
print("=" * 60)

# Get all stations from both forward and reverse graph
all_stations = set()
for s in graph_forward:
    all_stations.add(s)
    for conn in graph_forward[s]:
        all_stations.add(conn['station'])

# For each station, check if 华阴站 is reachable from it (forward)
for station in sorted(all_stations):
    # BFS forward from this station
    visited_local = set()
    queue = deque([station])
    visited_local.add(station)

    while queue:
        current = queue.popleft()
        if current in graph_forward:
            for conn in graph_forward[current]:
                next_station = conn['station']
                if next_station not in visited_local:
                    visited_local.add(next_station)
                    queue.append(next_station)

    reaches_hy = target in visited_local

    # Check if this station is reachable from 华阴站 (reverse)
    # BFS backward from this station
    visited_back = set()
    queue = deque([station])
    visited_back.add(station)

    while queue:
        current = queue.popleft()
        if current in graph_reverse:
            for conn in graph_reverse[current]:
                next_station = conn['station']
                if next_station not in visited_back:
                    visited_back.add(next_station)
                    queue.append(next_station)

    hy_reaches_this = target in visited_back

    if reaches_hy or hy_reaches_this:
