import csv, os
from pathlib import Path
from collections import defaultdict

DIR = Path(os.environ["NODE_FLOW_DIR"])

stations = ["上海站", "安平站"]
files = ["20191129_node.csv", "20191130_node.csv", "20191201_node.csv"]

# daily totals per station (sum of abs calc flow across their pipeline rows)
daily = {f: defaultdict(float) for f in files}
grand = defaultdict(float)

for f in files:
    with open(DIR / f, encoding="utf-8-sig") as fh:
        reader = csv.DictReader(fh)
        for row in reader:
            station = row["站名"].strip()
            if station in stations:
                val = float(row["计算流量"])
                daily[f][station] += abs(val)
                grand[station] += abs(val)

print("=== 全量汇总 (3天) ===")
for s in stations:
    print(f"{s}: {grand[s]:.3f}")

print("\n=== 每日汇总 ===")
for f in files:
    for s in stations:
        print(f"{f} {s}: {daily[f][s]:.3f}")

# Identify peak day by combined total across both stations
combined = {f: daily[f]["上海站"] + daily[f]["安平站"] for f in files}
peak = max(combined, key=combined.get)
print(f"\n=== 峰值日: {peak} (combined={combined[peak]:.3f}) ===")
print("各日combined:", combined)

# Recompute excluding peak day
grand2 = defaultdict(float)
for f in files:
    if f == peak:
        continue
    for s in stations:
        grand2[s] += daily[f][s]

print("\n=== 剔除峰值日后 ===")
for s in stations:
    print(f"{s}: {grand2[s]:.3f}")

diff = grand2["上海站"] - grand2["安平站"]
print(f"\n差值: {diff:.3f}")
if grand2["上海站"] > grand2["安平站"]:
    print("结论不反转：上海站仍高于安平站")
else:
    print("结论反转：安平站高于上海站")

